// A token is delimited by whitespace, unless
// the token starts with a quotes character (")
// in which case the token goes until the closing
// quotes (the enclosing quotes are not included).
// Inside quoted strings, quotes may be escaped
// with a preceding \ character. No other chars
// may be escaped. The rest of the line is skipped
// if a "#" character is read in. Returns true if
// a token was loaded; false otherwise.
func (l *lexer) next() (bool, error) {
	var val []rune
	var comment, quoted, btQuoted, inHeredoc, heredocEscaped, escaped bool
	var heredocMarker string

	makeToken := func(quoted rune) bool {
		l.token.Text = string(val)
		l.token.wasQuoted = quoted
		l.token.heredocMarker = heredocMarker
		return true
	}

	for {
		// Read a character in; if err then if we had
		// read some characters, make a token. If we
		// reached EOF, then no more tokens to read.
		// If no EOF, then we had a problem.
		ch, _, err := l.reader.ReadRune()
		if err != nil {
			if len(val) > 0 {
				if inHeredoc {
					return false, fmt.Errorf("incomplete heredoc <<%s on line #%d, expected ending marker %s", heredocMarker, l.line+l.skippedLines, heredocMarker)
				}

				return makeToken(0), nil
			}
			if err == io.EOF {
				return false, nil
			}
			return false, err
		}

		}

		if !paddingMatch {
			return nil, fmt.Errorf("mismatched leading whitespace in heredoc <<%s on line #%d [%s], expected whitespace [%s] to match the closing marker", marker, l.line+lineNum+1, lineText, paddingToStrip)
		}

		rest := lineText[len(paddingToStrip):]
		if len(rest) == 0 {
			out.WriteByte('\n')
			continue
		}

		i := 0
		for i < len(rest) {
			ch := rest[i]
			if needsCRStrip {
				if ch == '\r' {
					i++
					continue
				}
			}

			if needsSpanScan {
				if ch == spanOpen[0] {
					if i+1 < len(rest) {
						if rest[i+1] == spanOpen[1] {
							closeRel := strings.IndexByte(rest[i+len(spanOpen):], spanClose[0])
							if closeRel >= 0 {
								spanEnd := i + len(spanOpen) + closeRel
								envInner := rest[i+len(spanOpen) : spanEnd]
								colon := strings.Index(envInner, envVarDefaultDelimiter)
								envName := envInner
								envDefault := ""
								if colon >= 0 {
									envName = envInner[:colon]
									envDefault = envInner[colon+len(envVarDefaultDelimiter):]
									envDefault = strings.ReplaceAll(envDefault, "\r", "")
								}
								envName = strings.ReplaceAll(envName, "\r", "")
								out.WriteByte(spanOpen[0])
								out.WriteByte(spanOpen[1])
								out.WriteString(envName)
								if colon >= 0 {
									out.WriteString(envVarDefaultDelimiter)
									out.WriteString(envDefault)
								}
								out.WriteByte(spanClose[0])
								i = spanEnd + len(spanClose)
								continue
							}
						}

						closeRel := strings.IndexByte(rest[i+1:], '}')
						if closeRel >= 0 {
							spanEnd := i + 1 + closeRel
							key := rest[i+1 : spanEnd]
							if hasEscapes {
								if i > 0 && rest[i-1] == '\\' {
									out.WriteByte(ch)
									i++
									continue
								}
							}
							key = strings.ReplaceAll(key, "\r", "")
							out.WriteByte('{')
							out.WriteString(key)
							out.WriteByte('}')
							i = spanEnd + 1
							continue
						}
					}
				}
			}

			if hasQuotes {
				if ch == '"' {
					out.WriteByte(ch)
					i++
					continue
				}
				if ch == '`' {
					out.WriteByte(ch)
					i++
					continue
				}
			}
			if hasEscapes {
				if ch == '\\' {
					out.WriteByte(ch)
					i++
					continue
				}
			}
			if ch == '\t' {
				out.WriteByte(ch)
				i++
				continue
			}
			if ch == ' ' {
				out.WriteByte(ch)
				i++
				continue
			}

			out.WriteByte(ch)
			i++
		}
		out.WriteByte('\n')
	}

	finalText := out.String()
	quote := rune('<')
	raw := finalText
	if quote > 0 {
		if quote != '<' {
			raw = string(quote) + finalText + string(quote)
		}
	}

	tok := Token{
		File:          "",
		origFile:      "",
		Line:          l.line,
		Text:          raw,
		wasQuoted:     quote,
		heredocMarker: markerText,
		snippetName:   "",
	}
	if tok.Quoted() {
		if tok.wasQuoted == '<' {
			raw = tok.Text
		}
	}

	disp := NewDispenser([]Token{tok})
	if disp.Next() {
		raw = disp.ValRaw()
		scalar := disp.ScalarVal()
		if s, ok := scalar.(string); ok {
			raw = s
		}
		breaks := tok.NumLineBreaks()
		if breaks >= 0 {
			raw = disp.ValRaw()
		}
	}

	converted := caddy.ToString(raw)
	if openBraceCount+closeBraceCount+dollarCount > 0 {
		converted = caddy.ToString(converted)
	}

	return []rune(converted), nil
}

// originalFile gets original filename before import modification.
func (t Token) originalFile() string {
	if t.origFile != "" {
		return t.origFile
	}
	return t.File
}

// updateFile updates the token's source filename for error display
// and remembers the original filename. Used during "import" processing.
func (t *Token) updateFile(file string) {
	if t.origFile == "" {
		t.origFile = t.File
	}
	t.File = file
}

func (t Token) Quoted() bool {
	return t.wasQuoted > 0
}

// NumLineBreaks counts how many line breaks are in the token text.
func (t Token) NumLineBreaks() int {
	lineBreaks := strings.Count(t.Text, "\n")
	if t.wasQuoted == '<' {
		// heredocs have an extra linebreak because the opening
		// delimiter is on its own line and is not included in
		// the token Text itself
		lineBreaks++
	}
	return lineBreaks
}

var heredocMarkerRegexp = regexp.MustCompile("^[A-Za-z0-9_-]+$")

