package main

import (
	"fmt"
	"math/rand"

	"github.com/caddyserver/caddy/v2/caddyconfig/caddyfile"
)

func main() {
	r := rand.New(rand.NewSource(1))
	alphabet := []byte("<>{}`\"\\$ \t\r\nabcEOF_-0123456789\x00\x01\xff\xbf\xc3\xa9")
	for i := 0; i < 300000; i++ {
		n := r.Intn(64)
		b := make([]byte, n)
		for j := range b {
			b[j] = alphabet[r.Intn(len(alphabet))]
		}
		func() {
			defer func() {
				if p := recover(); p != nil {
					fmt.Printf("panic on input %q: %v\n", b, p)
					panic(p)
				}
			}()
			_, _ = caddyfile.Tokenize(b, "fuzz")
		}()
	}
	fmt.Println("ok")
}
EOF
